{
  "missionStatement": "Research and document the chemistry and physics of room-temperature superconductors, updating all repository documents with recent findings and proposing new compounds and manufacturing methods.",
  "criteria": [
    {
      "description": "Literature review updated with recent (2020+) papers on hydride superconductors and other promising systems, with citations.",
      "expectedFiles": ["literature_review.md", "docs/literature_review.md"]
    },
    {
      "description": "Theoretical framework includes a proposed mechanism (e.g., BCS-like, excitonic, or novel) for room-temperature superconductivity, with supporting references.",
      "expectedFiles": ["theoretical_framework.md", "docs/theoretical_framework.md", "docs/novel_mechanism.md"]
    },
    {
      "description": "Candidate materials list expanded to include at least 5 new compounds with predicted Tc > 300K, with references and predicted properties.",
      "expectedFiles": ["candidate_materials.md", "docs/candidate_materials.md", "data/superconductor_database.json"]
    },
    {
      "description": "Synthesis methods document updated to include high-pressure synthesis, chemical doping, and thin-film growth techniques relevant to candidate materials.",
      "expectedFiles": ["synthesis_methods.md", "docs/synthesis_methods.md", "docs/experimental_protocol_hydride.md"]
    },
    {
      "description": "Characterization techniques document updated to include advanced methods (e.g., muon spin rotation, neutron scattering) and their application to candidate materials.",
      "expectedFiles": ["characterization_techniques.md", "docs/characterization_techniques.md"]
    },
    {
      "description": "Roadmap updated with specific milestones for discovery, validation, and manufacturing scale-up, including timelines and resource estimates.",
      "expectedFiles": ["roadmap.md", "docs/roadmap.md"]
    },
    {
      "description": "Data file superconductor_database.json updated with new entries from literature, including Tc, pressure, composition, and reference.",
      "expectedFiles": ["data/superconductor_database.json"]
    },
    {
      "description": "Script predict_tc.py updated to incorporate new models (e.g., BCS, Eliashberg) and output predictions for candidate materials.",
      "expectedFiles": ["scripts/predict_tc.py"]
    },
    {
      "description": "Script query_database.py updated to allow filtering by Tc, pressure, and composition, with improved output formatting.",
      "expectedFiles": ["scripts/query_database.py"]
    },
    {
      "description": "Document docs/manufacturing_scalability.md updated with detailed manufacturing pathways, cost analysis, and scalability challenges.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Document docs/challenges_and_mitigations.md updated with current challenges (e.g., stability, cost) and proposed solutions.",
      "expectedFiles": ["docs/challenges_and_mitigations.md"]
    },
    {
      "description": "Document docs/experimental_feedback_loop.md updated with iterative testing workflow, including data analysis and model refinement.",
      "expectedFiles": ["docs/experimental_feedback_loop.md"]
    },
    {
      "description": "README updated to reflect new findings, updated navigation, and links to new or updated documents.",
      "expectedFiles": ["README.md"]
    },
    {
      "description": "All updated documents include citations to primary sources from web research, with URLs and key excerpts.",
      "expectedFiles": []
    }
  ]
}

{
  "missionStatement": "Conduct a comprehensive study (including online research) of superconducting materials and propose novel chemistry and physics for discovering and manufacturing room-temperature superconducting compounds, updating the repository with findings and actionable hypotheses.",
  "criteria": [
    {
      "description": "Literature review updated with at least 5 new references from 2020+ papers on room-temperature superconductivity, including key findings and identified gaps, with citations.",
      "expectedFiles": ["literature_review.md", "docs/literature_review.md"]
    },
    {
      "description": "Theoretical framework expanded to include novel mechanisms (e.g., BCS-like, excitonic, topological, hydride-based) for room-temperature superconductivity, with supporting references.",
      "expectedFiles": ["theoretical_framework.md", "docs/theoretical_framework.md"]
    },
    {
      "description": "Novel mechanism document proposes a specific new physics model (e.g., electron-phonon coupling enhancement via lattice anharmonicity) with supporting calculations.",
      "expectedFiles": ["docs/novel_mechanism.md"]
    },
    {
      "description": "Candidate materials list updated with at least 5 new compounds with predicted Tc > 300K, including synthesis feasibility and key references.",
      "expectedFiles": ["candidate_materials.md", "docs/candidate_materials.md"]
    },
    {
      "description": "Synthesis methods document updated with high-pressure synthesis, chemical doping, and thin-film growth techniques relevant to candidate materials, including a detailed experimental protocol for hydride synthesis.",
      "expectedFiles": ["synthesis_methods.md", "docs/synthesis_methods.md", "docs/experimental_protocol_hydride.md"]
    },
    {
      "description": "Characterization techniques document updated with advanced methods (e.g., muon spin rotation, neutron scattering, ARPES, STM, resonant inelastic X-ray scattering) for verifying room-temperature superconductivity.",
      "expectedFiles": ["characterization_techniques.md", "docs/characterization_techniques.md"]
    },
    {
      "description": "Roadmap updated with specific milestones for discovery, validation, and manufacturing scale-up, including timelines and resource estimates.",
      "expectedFiles": ["roadmap.md", "docs/roadmap.md"]
    },
    {
      "description": "Superconductor database updated with new entries for candidate materials, including Tc, pressure, composition, crystal structure, synthesis parameters, and references.",
      "expectedFiles": ["data/superconductor_database.json"]
    },
    {
      "description": "Prediction script updated to incorporate new theoretical models (e.g., BCS, Eliashberg, machine learning) and output Tc estimates for novel candidates.",
      "expectedFiles": ["scripts/predict_tc.py"]
    },
    {
      "description": "Query database script updated to support filtering by Tc, pressure, composition, mechanism type, and pressure range, with improved output formatting.",
      "expectedFiles": ["scripts/query_database.py"]
    },
    {
      "description": "Manufacturing scalability document updated with detailed manufacturing pathways, cost analysis, and scalability challenges for large-scale production.",
      "expectedFiles": ["docs/manufacturing_scalability.md"]
    },
    {
      "description": "Challenges and mitigations document updated with current challenges (e.g., stability, cost) and proposed solutions.",
      "expectedFiles": ["docs/challenges_and_mitigations.md"]
    },
    {
      "description": "Experimental feedback loop document updated with iterative hypothesis testing workflow, including data analysis and model refinement.",
      "expectedFiles": ["docs/experimental_feedback_loop.md"]
    },
    {
      "description": "All updated documents include proper citations with URLs to primary sources and a references section.",
      "expectedFiles": []
    }
  ]
}

